function getTargetBaseDir(target, c) {
  if (target === 'project') {
    return join(c, '.agents', 'skills')
  }

  const agent =
    getAgentByFlag(target) ||
    agents.find((candidate) => candidate.name === target)

  const baseDir = agent ? agent.getDir() : getAgentsDir()

  return rebaseToCwd(baseDir, c)
}
